namespace Idasletten.Features.Tournaments;

/// <summary>Has one or more TournamentPlayers. Name and Number are autogenerated.</summary>
public class TournamentTeam
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid TournamentId { get; set; }

    /// <summary>Autogenerated: "Team 1", "Team 2", ...</summary>
    public string Name { get; set; } = "";

    /// <summary>Autogenerated: 1, 2, ...</summary>
    public int Number { get; set; }

    public List<TournamentPlayer> Players { get; set; } = [];
}
